import unittest
from logic import solve
class ContractRegression(unittest.TestCase):
 def test_contract_boundaries(self):
  for value,expected in [({'text': '1m 250ms'}, 60250), ({'text': '3ms 2s 1m'}, 62003), ({'text': '2h'}, None), ({'text': '-1s'}, None), ({'text': '2sx'}, None)]:
   with self.subTest(value=value):
    try:actual=solve(value)
    except Exception as error:self.fail(f"contract raised {type(error).__name__}: {error}")
    else:self.assertEqual(actual,expected)
